using Microsoft.AspNetCore.Mvc;using NovaStore.Models;using NovaStore.Services;
namespace NovaStore.Controllers;public class CheckoutController(StoreService store):Controller {public IActionResult Index(){var lines=HttpContext.Session.Details(store);if(lines.Count==0)return RedirectToAction("Index","Cart");ViewBag.Lines=lines;return View(new CheckoutInput());}[HttpPost,ValidateAntiForgeryToken]public IActionResult Index(CheckoutInput input){var lines=HttpContext.Session.Details(store);if(lines.Count==0)return RedirectToAction("Index","Cart");if(!ModelState.IsValid){ViewBag.Lines=lines;return View(input);}if(lines.Any(x=>x.Quantity>x.Product.Stock)){ModelState.AddModelError("","Some items are out of stock. Please update your cart.");ViewBag.Lines=lines;return View(input);}var sub=lines.Sum(x=>x.Total);var order=new Order{Id="NV-"+DateTime.UtcNow.ToString("yyyyMMdd")+"-"+Guid.NewGuid().ToString("N")[..6].ToUpperInvariant(),Customer=input,Subtotal=sub,Shipping=sub>=200?0:15,Items=lines.Select(x=>new OrderItem{Name=x.Product.Name,Price=x.Product.Price,Quantity=x.Quantity,Image=x.Product.Image}).ToList()};store.AddOrder(order);foreach(var line in lines){var item=store.Find(line.Product.Id)!;item.Stock-=line.Quantity;store.Upsert(item);}HttpContext.Session.SetCart(new());return RedirectToAction("Success",new{id=order.Id});}public IActionResult Success(string id){var order=store.Orders().FirstOrDefault(x=>x.Id==id);return order==null?NotFound():View(order);}}
